export function privateShouldBeEncrypted(client: MatrixClient): boolean {
    const e2eeWellKnown = getE2EEWellKnown(client);
    if (e2eeWellKnown) {
        const defaultDisabled = e2eeWellKnown["default"] === false;
        return !defaultDisabled;
    }
    return true;
}
